// Package config layers runtime config (config/app.yaml) over machine-
// generated defaults (gen/defaults.gen.json — regenerated by configgen, do
// not edit).
package config

import (
	"encoding/json"
	"os"
	"strconv"
	"sync"
)

var (
	once     sync.Once
	defaults map[string]any
)

func load() {
	defaults = map[string]any{}
	raw, err := os.ReadFile("gen/defaults.gen.json")
	if err != nil {
		return
	}
	_ = json.Unmarshal(raw, &defaults)
}

// OrderRetryLimit returns how many capture attempts billing.ProcessOrder may
// make. Sourced from the generated defaults; override with ORDER_RETRY_LIMIT.
func OrderRetryLimit() int {
	if env := os.Getenv("ORDER_RETRY_LIMIT"); env != "" {
		if n, err := strconv.Atoi(env); err == nil {
			return n
		}
	}
	once.Do(load)
	if v, ok := defaults["order_retry_limit"].(float64); ok {
		return int(v)
	}
	return 3 // last-ditch fallback if the generated defaults are missing
}
